import pandas as pd, numpy as np, lightgbm as lgb
from sklearn.model_selection import KFold
import statsmodels.api as sm

df=pd.read_csv('data.csv')
X_cols=['log_hist_days','region','log_pre_gmv','orders','cat_share','tenure','tier']
X=df[X_cols].values; D=df.D.values; DA=np.maximum(D-16,0); Y=df.dY.values

def lgb_fit(Xtr,ytr,seed):
    return lgb.LGBMRegressor(n_estimators=300,learning_rate=0.03,num_leaves=31,min_child_samples=20,subsample=0.8,colsample_bytree=0.8,verbose=-1,random_state=seed).fit(Xtr,ytr)

def dml_piece(seed_fold=123, seed_lgb=42):
    kf=KFold(n_splits=5,shuffle=True,random_state=seed_fold)
    rD=np.empty_like(D); rDA=np.empty_like(D); rY=np.empty_like(D)
    for tr,te in kf.split(X):
        md=lgb_fit(X[tr],D[tr],seed_lgb); mda=lgb_fit(X[tr],DA[tr],seed_lgb+1); my=lgb_fit(X[tr],Y[tr],seed_lgb+2)
        rD[te]=D[te]-md.predict(X[te]); rDA[te]=DA[te]-mda.predict(X[te]); rY[te]=Y[te]-my.predict(X[te])
    R=sm.add_constant(np.column_stack([rD,rDA]))
    m=sm.OLS(rY,R).fit(cov_type='HC3')
    return m.params[1], m.params[1]+m.params[2], m.bse[1], np.sqrt(np.array([0,1,1])@m.cov_params()@np.array([0,1,1]))

for sf in [123,42,2024]:
    for sl in [42,7]:
        b,slope,seb,ses=dml_piece(sf,sl)
        print(f'foldseed {sf} lgb {sl}: beta {b:.4f}({seb:.4f}) slope>16 {slope:.4f}({ses:.4f})')
